// Prepare Data: validate the form, store the lead (so the visitor's page can poll for replies)
// and decide what happens next.
//   route "send"    -> new lead: build the Excel file and deliver it to Telegram
//   route "respond" -> nothing to deliver (identical re-submit, or bot trap): answer the page right away
//   route "reject"  -> answer the page with an error status
const TTL_MS = 72 * 3600 * 1000;   // how long a lead and its replies stay available to the visitor's page
const DUP_MS = 10 * 60 * 1000;     // an identical re-submit inside this window reuses the first lead
const FLOOD_MAX = 30;              // max new leads per 10 minutes (keeps the Telegram chat safe from spam)
const TZ = 'Asia/Tehran';

const now = Date.now();
const sd = $getWorkflowStaticData('global');
sd.leads = sd.leads || {};
sd.recent = (sd.recent || []).filter(t => now - t < 10 * 60 * 1000);
for (const k of Object.keys(sd.leads)) if (now - sd.leads[k].createdAt > TTL_MS) delete sd.leads[k];

const b = $input.first().json.body || {};
const reject = (status, error) => [{ json: { route: 'reject', ok: false, status, error, now } }];
const clean = (v, n) => String(v == null ? '' : v).replace(/[\u0000-\u001f\u007f‎‏‪-‮⁦-⁩]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, n);
const latin = s => s.replace(/[۰-۹]/g, d => '۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d));
const normPhone = p => {
  p = latin(p).replace(/[\s\-().]/g, '');
  if (/^\+98/.test(p)) p = '0' + p.slice(3); else if (/^0098/.test(p)) p = '0' + p.slice(4); else if (/^9\d{9}$/.test(p)) p = '0' + p;
  return p;
};

// Hidden "website" field: humans leave it empty, bots fill it. Pretend success, deliver nothing.
if (clean(b.website, 80)) {
  return [{ json: { route: 'respond', ok: true, id: 'NL-00000', token: 'x'.repeat(24), createdAt: now, now, hasPhone: true } }];
}

const firstName = clean(b.firstName, 60);
const lastName = clean(b.lastName, 60);
const ageRaw = latin(clean(b.age, 4));
const age = ageRaw ? Math.floor(Number(ageRaw)) : null;   // optional
const email = clean(b.email, 120).toLowerCase();
const phone = normPhone(clean(b.phone, 24));              // optional, but the page warns when it is missing
const services = (Array.isArray(b.services) ? b.services : []).slice(0, 12).map(s => ({
  category: clean(s && s.category, 60),
  items: (Array.isArray(s && s.items) ? s.items : []).slice(0, 30).map(i => clean(i, 60)).filter(Boolean)
})).filter(s => s.category);

if (!firstName) return reject(400, 'name');
if (ageRaw && !(age > 0 && age < 121)) return reject(400, 'age');
if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return reject(400, 'email');
if (phone && !/^09\d{9}$/.test(phone)) return reject(400, 'phone');
if (!services.length) return reject(400, 'services');

// Same person pressing submit twice (or retrying after a flaky connection): reuse the delivered lead.
const fp = [firstName, lastName, age, email, phone, JSON.stringify(services)].join('|');
for (const k of Object.keys(sd.leads)) {
  const L = sd.leads[k];
  if (L.fp === fp && L.delivered && now - L.createdAt < DUP_MS) {
    return [{ json: { route: 'respond', ok: true, id: L.id, token: L.token, createdAt: L.createdAt, now, hasPhone: !!L.phone, duplicate: true } }];
  }
}

// Telegram bots can only write to people who pressed Start in the bot: that chat is saved by "Handle Telegram Update".
if (!sd.operatorChatId) return reject(503, 'operator_not_linked');
if (sd.recent.length >= FLOOD_MAX) return reject(429, 'too_many');

function rnd(n, alpha) {
  const lim = 256 - (256 % alpha.length);
  let s = '';
  while (s.length < n) {
    let bytes;
    try { bytes = crypto.getRandomValues(new Uint8Array(n * 2)); }
    catch (e) { bytes = Array.from({ length: n * 2 }, () => Math.floor(Math.random() * 256)); }
    for (const x of bytes) if (x < lim && s.length < n) s += alpha[x % alpha.length];
  }
  return s;
}
let id;
do { id = 'NL-' + rnd(5, 'ABCDEFGHJKMNPQRSTUVWXYZ23456789'); } while (Object.values(sd.leads).some(l => l.id === id));
const token = rnd(24, 'abcdefghjkmnpqrstuvwxyz23456789');   // secret the visitor's page uses to read the replies

const d = new Date(now);
let createdFa;
try {
  createdFa = new Intl.DateTimeFormat('fa-IR-u-ca-persian', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false }).format(d);
} catch (e) { createdFa = d.toISOString(); }

const lead = {
  id, token, createdAt: now, createdFa, createdIso: d.toISOString(),
  firstName, lastName, age, email, phone, services, fp,
  delivered: false, tgMsgId: null, replies: [],
  closed: false, closedAt: null, phoneRequested: false, phoneEdits: 0
};
sd.leads[token] = lead;
sd.recent.push(now);

let caption = [
  `🆕 درخواست جدید  ${id}`,
  '',
  `👤 ${(firstName + ' ' + lastName).trim()}`,
  phone ? `📞 ${phone}` : '📵 شماره موبایل وارد نشده؛ با دکمه «📞 درخواست شماره» از متقاضی بخواهید شماره‌اش را ثبت کند.',
  age ? `🎂 سن: ${age}` : null,
  email ? `✉️ ${email}` : null,
  '',
  '💆 خدمات انتخابی:',
  ...services.map(s => `• ${s.category}${s.items.length ? ': ' + s.items.join('، ') : ''}`),
  '',
  `🕒 ${createdFa}`,
  '',
  '✍️ برای پاسخ، دکمه «پاسخ به متقاضی» را بزنید یا روی همین پیام Reply کنید.'
].filter(x => x !== null).join('\n');
if (caption.length > 1000) caption = caption.slice(0, 997) + '...';

return [{ json: { route: 'send', chatId: sd.operatorChatId, caption, lead } }];

// Build Excel Row: one row with every field of the lead, in the order the sheet should show them.
const L = $input.first().json.lead;
return [{
  json: {
    'شناسه': L.id,
    'تاریخ ثبت': L.createdFa,
    'نام': L.firstName,
    'نام خانوادگی': L.lastName,
    'سن': L.age == null ? '' : L.age,
    'جیمیل': L.email,
    'شماره تماس': L.phone || 'وارد نشده',
    'دسته‌ها': L.services.map(s => s.category).join('، '),
    'خدمات انتخابی': L.services.map(s => s.category + (s.items.length ? ': ' + s.items.join('، ') : '')).join(' | '),
    'زمان ثبت (UTC)': L.createdIso
  }
}];

// Save Message Id: remember which Telegram message belongs to which lead,
// so a Reply to that message in Telegram finds its lead. Then answer the page.
const sd = $getWorkflowStaticData('global');
const p = $('Prepare Data').first().json;
const r = $input.first().json || {};
const msg = r.result || r;
const L = (sd.leads || {})[p.lead.token];
if (L) {
  L.delivered = true;
  if (msg.message_id != null) L.tgMsgId = msg.message_id;
}
return [{ json: { ok: true, id: p.lead.id, token: p.lead.token, createdAt: p.lead.createdAt, now: Date.now(), hasPhone: !!p.lead.phone } }];

// Lookup Status: the visitor's page asks "where is my request?" with its secret token.
// Read-only on purpose: it runs every few seconds, so it never writes to static data.
const TTL_MS = 72 * 3600 * 1000;
const sd = $getWorkflowStaticData('global');
const t = String(($input.first().json.query || {}).t || '');
const leads = sd.leads || {};
const now = Date.now();
const live = l => l && now - l.createdAt <= TTL_MS;
const L = t ? leads[t] : null;
if (!live(L)) return [{ json: { ok: false, status: 'expired', now } }];

const status = L.closed ? 'closed' : L.replies.length ? 'answered' : 'waiting';
// place in the waiting list: open requests with no reply yet that arrived earlier, plus this one
const queue = status !== 'waiting' ? 0
  : 1 + Object.values(leads).filter(o => o !== L && live(o) && o.delivered && !o.closed && !o.replies.length && o.createdAt < L.createdAt).length;

return [{ json: {
  ok: true, status, id: L.id, createdAt: L.createdAt, now,
  replies: L.replies.map(r => ({ text: r.text, at: r.at, kind: r.kind || 'text' })),
  hasPhone: !!L.phone, phoneRequested: !!L.phoneRequested, queue, closedAt: L.closedAt || null
} }];

// Save Phone: the visitor adds (or corrects) their mobile number after sending the request.
// The number is stored on the lead and the operator gets a Telegram message with it.
const TTL_MS = 72 * 3600 * 1000;
const MAX_EDITS = 5;                 // how many times one request may change its number

const sd = $getWorkflowStaticData('global');
sd.leads = sd.leads || {};
const b = $input.first().json.body || {};
const now = Date.now();
const respond = resp => [{ json: { route: 'respond', resp } }];
const latin = s => String(s == null ? '' : s).replace(/[۰-۹]/g, d => '۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d));
const normPhone = p => {
  p = latin(p).slice(0, 24).replace(/[\s\-().‎‏⁦-⁩]/g, '');
  if (/^\+98/.test(p)) p = '0' + p.slice(3); else if (/^0098/.test(p)) p = '0' + p.slice(4); else if (/^9\d{9}$/.test(p)) p = '0' + p;
  return p;
};
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const t = String(b.t || '');
const L = t ? sd.leads[t] : null;
if (!L || now - L.createdAt > TTL_MS) return respond({ ok: false, error: 'expired' });
const phone = normPhone(b.phone);
if (!/^09\d{9}$/.test(phone)) return respond({ ok: false, error: 'phone' });
if (L.phone === phone) return respond({ ok: true, phone });
if ((L.phoneEdits || 0) >= MAX_EDITS) return respond({ ok: false, error: 'too_many' });

const before = L.phone;
L.phone = phone;
L.phoneEdits = (L.phoneEdits || 0) + 1;
L.phoneAt = now;
if (!sd.operatorChatId || !L.delivered) return respond({ ok: true, phone });

const name = (L.firstName + ' ' + (L.lastName || '')).trim();
const text = [
  before ? '📞 <b>شماره موبایل متقاضی تغییر کرد</b>' : '📞 <b>متقاضی شماره موبایلش را ثبت کرد</b>',
  '',
  `<code>${L.id}</code>  ${esc(name)}`,
  `شماره: <code>${phone}</code>` + (before ? `  (قبلی: ${before})` : ''),
  L.phoneRequested && !before ? 'در پاسخ به «درخواست شماره» شما.' : null,
  '',
  'برای پاسخ دادن به متقاضی، روی همین پیام Reply کنید.'
].filter(x => x !== null).join('\n');

return [{ json: { route: 'notify', chatId: sd.operatorChatId, text, leadId: L.id, resp: { ok: true, phone } } }];

// Handle Telegram Update: runs for every message and button press the bot receives.
//  - the operator's chat is linked on any message (so leads can be sent there)
//  - buttons under each lead:  ✍️ reply   📞 ask for the mobile number   ✅ finish (leaves the waiting list)
//  - a reply to a lead message (or to the bot's "write your reply" prompt) is shown on the visitor's page
//  - /list or the "📋 لیست انتظار" keyboard button shows the waiting list
// Every item returned has an "action" that the Route node sends to the matching Telegram node.
const OPERATOR = 'AvidMechanic';     // Telegram username (without @) that receives and answers the requests
const TTL_MS = 72 * 3600 * 1000;
const LIST_BTN = '📋 لیست انتظار';
const PHONE_ASK = 'لطفاً شماره موبایل خود را در کادر زیر وارد کنید تا همکاران ما برای مشاوره و تعیین وقت با شما تماس بگیرند.';

const sd = $getWorkflowStaticData('global');
sd.leads = sd.leads || {};
const upd = $input.first().json;
const now = Date.now();

// Telegram can deliver the same update twice: skip ones we have already handled.
sd.seen = sd.seen || [];
if (upd.update_id != null) {
  if (sd.seen.includes(upd.update_id)) return [];
  sd.seen.push(upd.update_id);
  if (sd.seen.length > 200) sd.seen.splice(0, sd.seen.length - 200);
}

const out = [];
const say = (chatId, text) => out.push({ json: { action: 'text', chatId, text } });
const prompt = (chatId, text) => out.push({ json: { action: 'prompt', chatId, text } });
const menu = (chatId, text) => out.push({ json: { action: 'menu', chatId, text } });
const answer = (queryId, text, alert) => out.push({ json: { action: 'answer', queryId, text: String(text || '').slice(0, 190), alert: !!alert } });

const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const faNum = n => String(n).replace(/\d/g, d => '۰۱۲۳۴۵۶۷۸۹'[d]);
const dur = s => {
  s = Math.max(0, Math.round(s));
  const h = Math.floor(s / 3600), mi = Math.floor((s % 3600) / 60), se = s % 60, p = [];
  if (h) p.push(faNum(h) + ' ساعت');
  if (mi) p.push(faNum(mi) + ' دقیقه');
  if (!h && (se || !mi)) p.push(faNum(se) + ' ثانیه');
  return p.join(' و ');
};
const nameOf = L => (L.firstName + ' ' + (L.lastName || '')).trim();
const short = (s, n) => (s.length > n ? s.slice(0, n - 1) + '…' : s);
const live = () => Object.values(sd.leads).filter(l => now - l.createdAt <= TTL_MS);
const byId = id => live().find(l => l.id === String(id || '').toUpperCase()) || null;
const isOperator = u => !!u && !u.is_bot && String(u.username || '').toLowerCase() === OPERATOR.toLowerCase();
const linked = chatId => !!sd.operatorChatId && String(chatId) === String(sd.operatorChatId);
const addReply = (L, text, kind) => {
  L.replies.push({ text: text.slice(0, 2000), at: now, kind });
  if (L.replies.length > 20) L.replies.shift();
  return L.replies.length === 1 ? `\n⏱ زمان پاسخ‌گویی: ${dur((now - L.createdAt) / 1000)}` : '';
};

function listText() {
  const open = live().filter(l => l.delivered && !l.closed).sort((a, b) => a.createdAt - b.createdAt);
  if (!open.length) return '📋 <b>لیست انتظار خالی است</b>\nهمه درخواست‌ها تکمیل شده‌اند.';
  const waiting = open.filter(l => !l.replies.length), talking = open.filter(l => l.replies.length);
  const lines = ['📋 <b>لیست انتظار</b>'];
  let room = 3500, hidden = 0;
  const add = s => { if (room - s.length < 0) { hidden++; return; } lines.push(s); room -= s.length; };
  if (waiting.length) {
    add(`\n⏳ <b>منتظر پاسخ (${faNum(waiting.length)})</b>`);
    waiting.forEach((l, i) => add(`${faNum(i + 1)}. <code>${l.id}</code>  ${esc(short(nameOf(l), 32))}\n      ⏱ ${dur((now - l.createdAt) / 1000)} انتظار  ${l.phone ? '📞 ' + l.phone : '📵 بدون شماره'}`));
  }
  if (talking.length) {
    add(`\n💬 <b>پاسخ داده شده، هنوز باز (${faNum(talking.length)})</b>`);
    talking.forEach((l, i) => add(`${faNum(i + 1)}. <code>${l.id}</code>  ${esc(short(nameOf(l), 32))}\n      آخرین پاسخ: ${dur((now - l.replies[l.replies.length - 1].at) / 1000)} پیش  ${l.phone ? '📞 ' + l.phone : '📵 بدون شماره'}`));
  }
  if (hidden) lines.push(`\n… و ${faNum(hidden)} مورد دیگر`);
  lines.push('', 'پاسخ: دکمه «✍️ پاسخ به متقاضی» زیر پیام همان درخواست، یا کد را اول پیام بنویسید (مثل <code>NL-AB3CD</code> متن پاسخ).', 'خارج کردن از لیست: دکمه «✅ اتمام درخواست».');
  return lines.join('\n');
}

/* ---------- button presses ---------- */
const cq = upd.callback_query;
if (cq) {
  const chat = cq.message && cq.message.chat;
  if (!chat || chat.type !== 'private') { answer(cq.id); return out; }
  if (isOperator(cq.from)) sd.operatorChatId = chat.id;
  if (!linked(chat.id)) { answer(cq.id, 'این دکمه فقط برای تیم نیو لایف فعال است.', true); return out; }
  const mm = /^([rpd]):(NL-[A-Z2-9]{5})$/.exec(String(cq.data || ''));
  const L = mm ? byId(mm[2]) : null;
  if (!L) { answer(cq.id, 'این درخواست پیدا نشد یا منقضی شده است (درخواست‌ها ۷۲ ساعت نگه داشته می‌شوند).', true); return out; }
  const chatId = chat.id, who = `<code>${L.id}</code> (${esc(short(nameOf(L), 40))})`;

  if (mm[1] === 'r') {                                   // ✍️ reply
    answer(cq.id, 'متن پاسخ را بنویسید');
    prompt(chatId, `✍️ پاسخ به ${who}\nمتن پاسخ را در جواب همین پیام بنویسید و بفرستید.` + (L.closed ? '\n(این درخواست تکمیل شده بود؛ با پاسخ شما دوباره باز می‌شود.)' : ''));
  } else if (mm[1] === 'p') {                            // 📞 ask for the number
    if (L.phone) answer(cq.id, `شماره این متقاضی ثبت شده است: ${L.phone}`, true);
    else if (L.closed) answer(cq.id, 'این درخواست تکمیل شده است.', true);
    else if (L.phoneRequested) answer(cq.id, 'درخواست شماره قبلاً برای متقاضی فرستاده شده است.', true);
    else {
      L.phoneRequested = true;
      const took = addReply(L, PHONE_ASK, 'phone');
      answer(cq.id, 'درخواست شماره فرستاده شد');
      say(chatId, `📞 از ${who} خواسته شد شماره موبایلش را وارد کند. به‌محض ثبت، همین‌جا خبرتان می‌کنم.` + took);
    }
  } else {                                               // ✅ finish
    if (L.closed) answer(cq.id, 'این درخواست قبلاً تکمیل شده است.', true);
    else {
      L.closed = true; L.closedAt = now;
      answer(cq.id, 'درخواست تکمیل شد');
      say(chatId, `✅ ${who} تکمیل شد و از لیست انتظار خارج شد. صفحه متقاضی هم «تکمیل شد» نشان می‌دهد.\nاگر لازم شد دوباره پاسخ بدهید، روی پیام درخواست Reply کنید؛ درخواست دوباره باز می‌شود.`);
    }
  }
  return out;
}

/* ---------- messages ---------- */
const m = upd.message;
if (!m || !m.chat || m.chat.type !== 'private' || !m.from || m.from.is_bot) return out;
const chatId = m.chat.id;
const text = String(m.text || '').trim();

// The operator is recognised by Telegram username, then remembered by chat id.
if (isOperator(m.from)) sd.operatorChatId = chatId;
if (!linked(chatId)) {
  if (/^\/start\b/i.test(text)) say(chatId, 'این ربات فقط برای تیم نیو لایف فعال است.');
  return out;
}

if (/^\/(start|help)\b/i.test(text)) {
  menu(chatId, [
    '✅ این حساب برای دریافت درخواست‌های نیو لایف فعال شد.',
    '',
    'هر درخواست جدید همراه با فایل اکسل و این دکمه‌ها همین‌جا می‌آید:',
    '✍️ <b>پاسخ به متقاضی</b>: متن شما همان لحظه در صفحه متقاضی نمایش داده می‌شود.',
    '📞 <b>درخواست شماره</b>: از متقاضی می‌خواهد شماره موبایلش را وارد کند؛ شماره که ثبت شد، همین‌جا می‌آید.',
    '✅ <b>اتمام درخواست</b>: درخواست را تکمیل می‌کند و از لیست انتظار خارج می‌کند.',
    '',
    `${LIST_BTN}: دکمه پایین صفحه یا دستور /list`
  ].join('\n'));
  return out;
}
if (/^\/(list|waiting)\b/i.test(text) || text === LIST_BTN || /^لیست( انتظار)?$/.test(text)) { say(chatId, listText()); return out; }
if (!text) { say(chatId, 'فقط پاسخ متنی پشتیبانی می‌شود.'); return out; }

const leads = live();
let lead = null, body = text;
const rt = m.reply_to_message;
if (rt) {
  if (rt.message_id != null) lead = leads.find(l => l.tgMsgId === rt.message_id) || null;
  if (!lead) {
    // a reply to the bot's prompt, phone notice or confirmation: they name exactly one request code
    const codes = [...new Set(String(rt.text || rt.caption || '').match(/NL-[A-Z2-9]{5}/g) || [])];
    if (codes.length === 1) lead = byId(codes[0]);
  }
}
if (!lead) {
  // fallback: start the message with the request code, e.g.  NL-AB3CD  متن پاسخ
  const c = /^#?\s*(NL-[A-Z2-9]{5})\b[\s:：\-–]*/i.exec(text);
  if (c) {
    lead = byId(c[1]);
    if (lead) body = text.slice(c[0].length).trim();
  }
}
if (!lead) { say(chatId, 'این پیام به هیچ درخواستی وصل نشد. زیر پیام همان درخواست دکمه «✍️ پاسخ به متقاضی» را بزنید، روی پیام درخواست Reply کنید، یا کد درخواست (مثل <code>NL-AB3CD</code>) را اول پیام بنویسید.'); return out; }
